"""Upload into /content and run %run /content/Nebula_Overnight_Colab.py."""
from pathlib import Path
import shutil,sys
import torch
if not torch.cuda.is_available(): raise RuntimeError('Select a GPU runtime first.')
original=Path('/content/nebula_improved/api')
project=Path('/content/nebula_v3/api')
copies={
 'model/checkpoints/improved-language.best.pt':'model/checkpoints/previous-language.best.pt',
 'model/checkpoints/improved-chat.best.pt':'model/checkpoints/previous-chat.best.pt',
 'model/data/stories-approved.jsonl':'model/data/stories-approved.jsonl',
 'model/data/improved-chat.jsonl':'model/data/improved-chat.jsonl',
 'model/data/stories-sources.json':'model/data/stories-sources.json',
 'model/data/public-sources.json':'model/data/public-sources.json',
 'model/DATA_SOURCES.md':'model/DATA_SOURCES.md',
 'nebula-rules.json':'nebula-rules.json',
}
required={'model/checkpoints/improved-language.best.pt','model/checkpoints/improved-chat.best.pt',
          'model/data/stories-approved.jsonl','model/data/improved-chat.jsonl','nebula-rules.json'}
for source_name,target_name in copies.items():
    target=project/target_name
    if target.exists(): continue
    source=original/source_name
    if not source.exists():
        if source_name in required:
            raise FileNotFoundError('The previous Colab training files are missing. Restore your improved checkpoints and datasets before starting V3: '+source_name)
        continue
    target.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(source,target)
print({'GPU':torch.cuda.get_device_name(0),'previousModelsPreserved':True,'project':str(project)},flush=True)
sources={'model/nebula.py': '"""Nebula\'s small, randomly initialized causal Transformer. No pretrained weights."""\nimport json\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nimport torch\nfrom torch import nn\n\nBOS, EOS, SYSTEM, USER, ASSISTANT, PAD = range(256, 262)\nVOCAB = 262\nROLES = {"system": SYSTEM, "user": USER, "assistant": ASSISTANT}\n\n@dataclass\nclass Config:\n    width: int = 128\n    heads: int = 4\n    layers: int = 2\n    context: int = 512\n\ndef config_for_preset(preset):\n    presets = {\n        \'smoke\': Config(width=64,heads=2,layers=1,context=256),\n        \'cpu\': Config(),\n        \'cpu-medium\': Config(width=192,heads=6,layers=4,context=1024),\n        \'cpu-large\': Config(width=256,heads=8,layers=6,context=1024),\n        \'gpu\': Config(width=384,heads=8,layers=6,context=2048),\n    }\n    if preset not in presets: raise ValueError(\'Unknown model preset\')\n    return presets[preset]\n\ndef encode(messages, answer_prefix=False):\n    tokens, learn = [BOS], [False]\n    for message in messages:\n        role = message["role"]\n        tokens.append(ROLES[role]); learn.append(False)\n        content = list(message["content"].encode("utf-8"))\n        tokens.extend(content); learn.extend([role == "assistant"] * len(content))\n        tokens.append(EOS); learn.append(role == "assistant")\n    if answer_prefix:\n        tokens.append(ASSISTANT); learn.append(False)\n    return tokens, learn\n\ndef pack_prompt(messages, context):\n    systems = [m for m in messages if m[\'role\'] == \'system\']\n    history = [m for m in messages if m[\'role\'] != \'system\']\n    if not history or history[-1][\'role\'] != \'user\': raise ValueError(\'A user question is required\')\n    prefix, _ = encode(systems)\n    selected = []\n    # Keep every system instruction and the full latest question; never silently cut rules.\n    available = context - len(prefix) - 2\n    for message in reversed(history):\n        chunk = encode([message])[0][1:]\n        if len(chunk) > available:\n            if not selected: raise ValueError(\'Rules and question exceed the model context\')\n            break\n        selected.insert(0, chunk); available -= len(chunk)\n    return prefix + [token for chunk in selected for token in chunk] + [ASSISTANT]\n\nclass Nebula(nn.Module):\n    def __init__(self, config):\n        super().__init__(); self.config = config\n        self.token = nn.Embedding(VOCAB, config.width)\n        self.position = nn.Embedding(config.context, config.width)\n        self.blocks = nn.ModuleList(nn.TransformerEncoderLayer(config.width, config.heads, config.width * 4, dropout=0.0, activation="gelu", batch_first=True, norm_first=True) for _ in range(config.layers))\n        self.norm = nn.LayerNorm(config.width)\n        self.output = nn.Linear(config.width, VOCAB, bias=False)\n        self.output.weight = self.token.weight\n        self.register_buffer(\'_causal_mask\',torch.ones(config.context,config.context,dtype=torch.bool).triu(1),persistent=False)\n        self.apply(self._initialize)\n\n    @staticmethod\n    def _initialize(module):\n        if isinstance(module, (nn.Linear, nn.Embedding)):\n            nn.init.normal_(module.weight, std=0.02)\n            if isinstance(module, nn.Linear) and module.bias is not None: nn.init.zeros_(module.bias)\n\n    def forward(self, tokens):\n        length = tokens.shape[1]\n        if length > self.config.context: raise ValueError("Context is too long")\n        value = self.token(tokens) + self.position(torch.arange(length, device=tokens.device))\n        causal = self._causal_mask[:length,:length]\n        for block in self.blocks: value = block(value, src_mask=causal)\n        return self.output(self.norm(value))\n\n    @torch.inference_mode()\n    def reply(self, messages, max_tokens=160, temperature=0.7):\n        self.eval()\n        encoded = pack_prompt(messages, self.config.context)\n        device = next(self.parameters()).device\n        tokens = torch.tensor([encoded], device=device)\n        result = []\n        for _ in range(min(max_tokens, self.config.context - len(encoded))):\n            logits = self(tokens)[:, -1, :].clone()\n            end = logits[:, EOS].clone(); logits[:, BOS:] = float(\'-inf\'); logits[:, EOS] = end\n            if temperature == 0: next_token = logits.argmax(-1, keepdim=True)\n            else: next_token = torch.multinomial(torch.softmax(logits / temperature, -1), 1)\n            value = int(next_token.item())\n            if value == EOS: break\n            result.append(value); tokens = torch.cat([tokens, next_token], dim=1)\n        return bytes(result).decode(\'utf-8\', errors=\'replace\').strip()\n\ndef save(model, path, metadata, training_state=None):\n    if any(not torch.isfinite(parameter).all() for parameter in model.parameters()):\n        raise ValueError(\'Checkpoint contains non-finite weights; existing saved weights were not replaced\')\n    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(\'.tmp\')\n    payload={\'format\': 1, \'config\': asdict(model.config), \'state\': model.state_dict(), \'metadata\': metadata}\n    if training_state is not None: payload[\'trainingState\']=training_state\n    torch.save(payload, temporary)\n    temporary.replace(path)\n\ndef load(path):\n    data = torch.load(path, map_location=\'cpu\', weights_only=True)\n    if data.get(\'format\') != 1: raise ValueError(\'Unsupported model checkpoint\')\n    model = Nebula(Config(**data[\'config\'])); model.load_state_dict(data[\'state\']); model.eval()\n    if any(not torch.isfinite(parameter).all() for parameter in model.parameters()):\n        raise ValueError(\'Checkpoint contains non-finite weights; resume from a healthy best checkpoint\')\n    return model, data.get(\'metadata\', {})\n', 'model/train.py': 'import argparse\nimport hashlib\nimport json\nimport random\nimport time\nimport itertools\nimport math\nfrom contextlib import nullcontext\nfrom pathlib import Path\nimport torch\nfrom torch.nn import functional as F\nfrom nebula import Config, Nebula, PAD, encode, load, save, config_for_preset\nfrom dataflow import read_jsonl, eligible\nfrom rules import with_owner_rules\n\nclass NumericalFailure(RuntimeError): pass\n\ndef examples(rows, context, include_owner_rules=False, objective=\'assistant\'):\n    result = []\n    for row in rows:\n        messages = row[\'messages\']\n        if objective == \'language\':\n            # Language pretraining uses continuous serialized text chunks, with no\n            # invented end-of-answer tokens at chunk boundaries. Chat tuning below\n            # uses complete replies instead.\n            prefix=encode(with_owner_rules([]) if include_owner_rules else [])[0]\n            body=encode(messages)[0][1:]\n            room=context+1-len(prefix)\n            if room<1: raise ValueError(\'Owner rules exceed model context\')\n            for offset in range(0,len(body),room):\n                tokens=prefix+body[offset:offset+room]\n                x=torch.tensor(tokens[:-1]); y=torch.tensor([-100]*(len(prefix)-1)+tokens[len(prefix):])\n                result.append((x,y))\n            continue\n        wrapped = with_owner_rules(messages) if include_owner_rules else messages\n        windows = [wrapped]\n        if len(encode(wrapped)[0]) > context + 1:\n            windows = []\n            for end in range(2,len(messages)+1,2):\n                for start in range(0,end,2):\n                    candidate=with_owner_rules(messages[start:end]) if include_owner_rules else messages[start:end]\n                    if len(encode(candidate)[0]) <= context+1:\n                        windows.append(candidate); break\n        for window in windows:\n            tokens, learn = encode(window)\n            x = torch.tensor(tokens[:-1]); y = torch.tensor([v if mask else -100 for v, mask in zip(tokens[1:], learn[1:])])\n            if (y != -100).any(): result.append((x, y))\n    return result\n\ndef partition_rows(rows, seed):\n    """Split original dialogues before creating windows, keeping duplicates together."""\n    training=[]; validation=[]\n    for row in rows:\n        identifier=hashlib.sha256(json.dumps(row[\'messages\'],sort_keys=True).encode()).hexdigest()\n        # Owned curriculum variants of one scenario stay in the same partition.\n        group=row.get(\'splitGroup\') if row.get(\'source\',{}).get(\'kind\')==\'seed\' else None\n        split_key=\'group:\'+group if isinstance(group,str) and group else identifier\n        score=int(hashlib.sha256((str(seed)+\':\'+split_key).encode()).hexdigest()[:8],16)\n        (validation if score%10==0 else training).append(row)\n    if not training or not validation: raise ValueError(\'Grouped split requires enough distinct conversations\')\n    return training,validation\n\ndef bucket_batches(data,batch_size,rng):\n    ordered=sorted(data,key=lambda pair:len(pair[0])); batches=[]\n    for offset in range(0,len(ordered),max(batch_size*32,32)):\n        bucket=ordered[offset:offset+max(batch_size*32,32)]; rng.shuffle(bucket)\n        batches.extend(bucket[i:i+batch_size] for i in range(0,len(bucket),batch_size))\n    rng.shuffle(batches)\n    return batches\n\ndef unique_windows(data,excluded=None):\n    seen=set(excluded or []); result=[]\n    for x,y in data:\n        identifier=hashlib.sha256(x.numpy().tobytes()+y.numpy().tobytes()).hexdigest()\n        if identifier in seen: continue\n        seen.add(identifier); result.append((x,y))\n    return result,seen\n\ndef loss(model, batch):\n    length = max(len(x) for x, _ in batch)\n    x = torch.full((len(batch), length), PAD, dtype=torch.long); y = torch.full_like(x, -100)\n    for i, (a, b) in enumerate(batch): x[i, :len(a)] = a; y[i, :len(b)] = b\n    device=next(model.parameters()).device\n    autocast=torch.autocast(\'cuda\',dtype=model._amp_dtype) if getattr(model,\'_amp_enabled\',False) else nullcontext()\n    with autocast:\n        return F.cross_entropy(model(x.to(device)).reshape(-1, 262), y.to(device).reshape(-1), ignore_index=-100)\n\ndef evaluate_loss(model, data, batch_size):\n    total = tokens = 0\n    for offset in range(0, len(data), batch_size):\n        batch = data[offset:offset+batch_size]\n        count = sum(int((y != -100).sum()) for _, y in batch)\n        total += float(loss(model, batch)) * count; tokens += count\n    return total / tokens if tokens else None\n\ndef train(args):\n    if args.steps < 1 or args.batch < 1 or args.threads < 1: raise ValueError(\'Positive steps, batch and threads required\')\n    if not math.isfinite(args.lr) or args.lr <= 0: raise ValueError(\'Learning rate must be finite and positive\')\n    continuous = getattr(args, \'continuous\', False)\n    save_every = getattr(args, \'save_every\', 100)\n    patience = getattr(args, \'patience\', 0)\n    if patience < 0: raise ValueError(\'Patience must be zero or positive\')\n    if save_every < 1: raise ValueError(\'Save interval must be positive\')\n    max_seconds=getattr(args,\'max_seconds\',0)\n    if not math.isfinite(max_seconds) or max_seconds<0: raise ValueError(\'Time limit must be zero or positive\')\n    torch.set_num_threads(args.threads); torch.manual_seed(args.seed); rng = random.Random(args.seed)\n    rows = read_jsonl(args.data)\n    snapshot = json.loads(Path(args.snapshot).read_text(encoding=\'utf-8\')) if args.snapshot else None\n    if any(row.get(\'source\', {}).get(\'kind\') == \'user\' for row in rows):\n        if continuous: raise ValueError(\'Continuous runs require seed/teacher data; user consent must be refreshed between bounded runs\')\n        if not snapshot or not 0 <= time.time() * 1000 - snapshot.get(\'createdAt\', 0) < 300000:\n            raise ValueError(\'User examples require a fresh consent check. Use scripts/model-data.mjs train.\')\n    # User records always require a fresh Firebase consent snapshot supplied by the wrapper.\n    rows = [row for row in rows if eligible(row, snapshot)]\n    if args.resume: model,resume_metadata=load(args.resume)\n    else: model,resume_metadata=Nebula(config_for_preset(args.preset)),{}\n    inherited_steps=resume_metadata.get(\'steps\',0)\n    requested_device=getattr(args,\'device\',\'cpu\')\n    device=\'cuda\' if requested_device==\'auto\' and torch.cuda.is_available() else \'cpu\' if requested_device==\'auto\' else requested_device\n    if device==\'cuda\' and not torch.cuda.is_available(): raise ValueError(\'CUDA GPU is unavailable in this PyTorch installation\')\n    model.to(device)\n    model._amp_enabled=device==\'cuda\' and getattr(args,\'amp\',False)\n    model._amp_dtype=torch.bfloat16 if device==\'cuda\' and torch.cuda.is_bf16_supported() else torch.float16\n    scaler=torch.amp.GradScaler(\'cuda\',enabled=model._amp_enabled and model._amp_dtype==torch.float16)\n    objective=getattr(args,\'objective\',\'assistant\')\n    grouped=getattr(args,\'grouped_split\',False)\n    if grouped:\n        train_rows,validation_rows=partition_rows(rows,args.seed)\n        training=examples(train_rows,model.config.context,True,objective)\n        validation=examples(validation_rows,model.config.context,True,objective)\n        training,seen_windows=unique_windows(training)\n        validation,_=unique_windows(validation,seen_windows)\n        data=training+validation\n    else:\n        data = examples(rows, model.config.context, include_owner_rules=True,objective=objective)\n        rng.shuffle(data); split = max(1, int(len(data) * .9)); training, validation = data[:split], data[split:]\n    if not training: raise ValueError(\'No approved training examples fit the model context\')\n    if grouped and not validation: raise ValueError(\'No validation conversations fit the model context\')\n    available_validation=len(validation)\n    max_validation=getattr(args,\'max_validation\',0)\n    if max_validation:\n        validation_rng=random.Random(args.seed+1)\n        validation=validation_rng.sample(validation,min(len(validation),max_validation))\n    validation.sort(key=lambda pair:len(pair[0]))\n    optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=.01)\n    with torch.no_grad(): initial = float(loss(model, training[:args.batch]))\n    if not math.isfinite(initial): initial=None\n    completed = 0\n    data_hash = hashlib.sha256(Path(args.data).read_bytes()).hexdigest()\n    best_path = Path(args.output).with_suffix(\'.best.pt\')\n    best_validation = float(\'inf\')\n    stale_checks = 0\n    batches=[]; epoch=0; completed_total_before=0\n    if best_path.exists():\n        _, previous = load(best_path)\n        if previous.get(\'dataSha256\') == data_hash and previous.get(\'seed\') == args.seed and previous.get(\'objective\',\'assistant\') == objective and previous.get(\'groupedSplit\',False) == grouped and previous.get(\'maxValidation\',0) == max_validation and previous.get(\'windowFormat\',1)==2:\n            previous_loss = previous.get(\'validationLoss\')\n            if isinstance(previous_loss, (int, float)): best_validation = previous_loss\n    state_enabled=getattr(args,\'save_training_state\',False)\n    if state_enabled and args.resume:\n        saved_state=torch.load(args.resume,map_location=\'cpu\',weights_only=True).get(\'trainingState\')\n        signature={\'dataSha256\':data_hash,\'objective\':objective,\'seed\':args.seed,\n                   \'batch\':args.batch,\'bucketed\':getattr(args,\'bucketed\',False),\n                   \'groupedSplit\':grouped,\'windowFormat\':2,\'maxValidation\':max_validation,\n                   \'amp\':model._amp_enabled,\'learningRate\':args.lr}\n        if saved_state and saved_state.get(\'signature\')==signature:\n            optimizer.load_state_dict(saved_state[\'optimizer\'])\n            scaler.load_state_dict(saved_state[\'scaler\'])\n            rng.setstate(saved_state[\'samplerRandom\'])\n            torch.set_rng_state(saved_state[\'torchRandom\'])\n            if device==\'cuda\' and saved_state.get(\'cudaRandom\'):\n                torch.cuda.set_rng_state_all(saved_state[\'cudaRandom\'])\n            batches=[[training[index] for index in batch] for batch in saved_state[\'remainingBatches\']]\n            epoch=saved_state[\'epoch\']; stale_checks=saved_state[\'staleChecks\']\n            completed_total_before=saved_state.get(\'stageSteps\',0)\n            print(json.dumps({\'trainingStateRestored\':True,\'previousStageSteps\':completed_total_before}),flush=True)\n        else:\n            print(json.dumps({\'trainingStateRestored\':False,\'reason\':\'legacy_checkpoint_or_new_training_configuration\'}),flush=True)\n    signature={\'dataSha256\':data_hash,\'objective\':objective,\'seed\':args.seed,\n               \'batch\':args.batch,\'bucketed\':getattr(args,\'bucketed\',False),\n               \'groupedSplit\':grouped,\'windowFormat\':2,\'maxValidation\':max_validation,\n               \'amp\':model._amp_enabled,\'learningRate\':args.lr}\n    training_indices={id(x):index for index,(x,_) in enumerate(training)}\n    def checkpoint(stopped=False,validate=True,reason=None):\n        nonlocal best_validation, stale_checks\n        model.eval()\n        current=validation_loss=None\n        if validate:\n            with torch.no_grad():\n                current = float(loss(model, training[:args.batch]))\n                validation_loss = evaluate_loss(model, validation, args.batch)\n            if not math.isfinite(current) or validation_loss is not None and not math.isfinite(validation_loss):\n                raise NumericalFailure(\'Non-finite checkpoint metric\')\n        report = {\'parameters\': sum(p.numel() for p in model.parameters()), \'steps\': inherited_steps+completed,\'stepsThisRun\':completed, \'trainingExamples\': len(training), \'validationExamples\': len(validation),\'availableValidationExamples\':available_validation,\'originalConversations\':len(rows), \'skippedExamples\': None if grouped else max(0,len(rows) - len(data)), \'initialLoss\': initial, \'finalLoss\': current, \'validationLoss\': validation_loss, \'seed\': args.seed, \'dataSha256\': data_hash, \'experimental\': True, \'qualityApproved\': False, \'stopped\': stopped,\'objective\':objective,\'groupedSplit\':grouped,\'maxValidation\':max_validation,\'device\':device,\'windowFormat\':2}\n        if reason: report[\'stopReason\']=reason\n        improved=validation_loss is not None and validation_loss < best_validation\n        if improved:\n            best_validation = validation_loss\n            stale_checks = 0\n        elif validation_loss is not None:\n            stale_checks += 1\n            if validation_loss > best_validation * 1.2:\n                print(\'Validation loss is worsening: this run is overfitting. More varied data is needed; Ctrl+C saves and stops.\', flush=True)\n        training_state=None\n        if state_enabled:\n            training_state={\'signature\':signature,\'optimizer\':optimizer.state_dict(),\'scaler\':scaler.state_dict(),\n                \'samplerRandom\':rng.getstate(),\'torchRandom\':torch.get_rng_state(),\n                \'cudaRandom\':torch.cuda.get_rng_state_all() if device==\'cuda\' else [],\n                \'remainingBatches\':[[training_indices[id(x)] for x,_ in batch] for batch in batches],\n                \'epoch\':epoch,\'staleChecks\':stale_checks,\'stageSteps\':completed_total_before+completed}\n            report[\'stageSteps\']=completed_total_before+completed\n            report[\'trainingStateIncluded\']=True\n        if state_enabled: save(model,args.output,report,training_state=training_state)\n        else: save(model,args.output,report)\n        if improved:\n            if state_enabled: save(model,best_path,report,training_state=training_state)\n            else: save(model,best_path,report)\n            print(json.dumps({\'bestCheckpoint\': str(best_path), \'validationLoss\': best_validation}), flush=True)\n        print(json.dumps({\'checkpoint\': str(args.output), **report}), flush=True)\n    # Save even before the first update, then periodically and on Ctrl+C.\n    started=time.monotonic(); trained_tokens=0\n    try:\n        # Resume already has a verified checkpoint and optimizer state. Avoid an\n        # extra validation check consuming patience before its first update.\n        if not (state_enabled and completed_total_before): checkpoint()\n        for step in itertools.count() if continuous else range(args.steps):\n            if getattr(args,\'bucketed\',False):\n                if not batches: batches=bucket_batches(training,args.batch,rng); epoch+=1\n                batch=batches.pop()\n            else: batch = [training[rng.randrange(len(training))] for _ in range(args.batch)]\n            model.train()\n            optimizer.zero_grad(set_to_none=True); value = loss(model, batch)\n            if not torch.isfinite(value): raise NumericalFailure(\'Non-finite training loss\')\n            scaler.scale(value).backward(); scaler.unscale_(optimizer)\n            gradient_norm=torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            if not torch.isfinite(gradient_norm): raise NumericalFailure(\'Non-finite gradients; optimizer update was blocked\')\n            scaler.step(optimizer); scaler.update()\n            completed = step + 1\n            trained_tokens+=sum(len(x) for x,_ in batch)\n            if step == 0 or completed % 25 == 0: print(json.dumps({\'step\': completed, \'loss\': round(float(value.detach()), 4),\'epoch\':epoch or None,\'tokensPerSecond\':round(trained_tokens/max(.001,time.monotonic()-started))}), flush=True)\n            if max_seconds and time.monotonic()-started>=max_seconds:\n                checkpoint(stopped=True,validate=False,reason=\'time_limit\')\n                return {\'steps\':completed,\'stopped\':True,\'reason\':\'time_limit\'}\n            if completed % save_every == 0:\n                checkpoint()\n                if patience and stale_checks >= patience:\n                    print(json.dumps({\'stopped\':\'validation_not_improving\',\'steps\':completed,\'bestCheckpoint\':str(best_path),\'note\':\'Latest weights and best validation weights are saved. Live website unchanged.\'}),flush=True)\n                    return {\'steps\':completed,\'stopped\':True,\'reason\':\'validation_not_improving\'}\n    except KeyboardInterrupt:\n        checkpoint(stopped=True,validate=False,reason=\'interrupted\')\n        print(\'Stopped. Latest weights saved; the live website was not changed.\', flush=True)\n        return {\'steps\': completed, \'stopped\': True}\n    except NumericalFailure:\n        optimizer.zero_grad(set_to_none=True)\n        try:\n            checkpoint(stopped=True,validate=False,reason=\'non_finite_loss_or_gradient\')\n            message=\'Stopped for a numerical error. Finite current weights saved without validation; the best checkpoint is preserved.\'\n        except ValueError:\n            message=\'Stopped for a numerical error. Invalid weights were not saved; existing checkpoints are preserved.\'\n        print(message+\' Resume from a healthy best checkpoint with a lower learning rate.\',flush=True)\n        return {\'steps\':completed,\'stopped\':True,\'reason\':\'non_finite_loss_or_gradient\'}\n    checkpoint()\n    report=load(args.output)[1]\n    return report\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=\'Train owned Nebula weights from scratch. CPU preset is experimental, not production quality.\')\n    parser.add_argument(\'--continuous\', action=\'store_true\'); parser.add_argument(\'--save-every\', type=int, default=100)\n    parser.add_argument(\'--save-training-state\',action=\'store_true\',help=\'Save and restore compatible optimizer, sampler and random states\')\n    parser.add_argument(\'--max-seconds\',type=float,default=0,help=\'Stop and save after this many seconds; 0 disables\')\n    parser.add_argument(\'--patience\', type=int, default=0, help=\'Stop after this many validation checks without improvement; 0 disables\')\n    parser.add_argument(\'--device\',choices=[\'auto\',\'cpu\',\'cuda\'],default=\'auto\')\n    parser.add_argument(\'--objective\',choices=[\'assistant\',\'language\'],default=\'assistant\')\n    parser.add_argument(\'--grouped-split\',action=\'store_true\'); parser.add_argument(\'--bucketed\',action=\'store_true\'); parser.add_argument(\'--max-validation\',type=int,default=0)\n    parser.add_argument(\'--data\', required=True); parser.add_argument(\'--output\', required=True); parser.add_argument(\'--snapshot\'); parser.add_argument(\'--resume\'); parser.add_argument(\'--preset\', choices=[\'cpu\', \'smoke\',\'cpu-medium\',\'cpu-large\',\'gpu\'], default=\'cpu\'); parser.add_argument(\'--steps\', type=int, default=500); parser.add_argument(\'--batch\', type=int, default=4); parser.add_argument(\'--threads\', type=int, default=2); parser.add_argument(\'--seed\', type=int, default=42); parser.add_argument(\'--lr\', type=float, default=.0005)\n    train(parser.parse_args())\n', 'model/dataflow.py': '"""Reviewed datasets. These commands never call teachers with user chat content."""\nimport hashlib\nimport json\nimport re\nfrom pathlib import Path\nfrom urllib.request import Request, urlopen\nfrom urllib.parse import urlparse\nimport os\nimport time\nfrom teacher_http import request_json\nfrom rules import owner_instructions\n\ndef read_jsonl(path):\n    with Path(path).open(encoding=\'utf-8\') as stream:\n        return [json.loads(line) for line in stream if line.strip()]\n\ndef write_jsonl(path, rows):\n    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(\'.tmp\')\n    temporary.write_text(\'\'.join(json.dumps(row, ensure_ascii=False) + \'\\n\' for row in rows), encoding=\'utf-8\')\n    temporary.replace(path)\n\ndef redact(text):\n    text = re.sub(r\'\\b[\\w.+-]+@[\\w.-]+\\.[a-zA-Z]{2,}\\b\', \'[email removed]\', text)\n    text = re.sub(r\'\\b(?:sk-|AIza)[\\w-]{15,}\\b\', \'[credential removed]\', text)\n    text = re.sub(r\'\\bBearer\\s+[\\w.~/+=-]{12,}\', \'[credential removed]\', text, flags=re.I)\n    text = re.sub(r\'(?<!\\w)(?:\\+?\\d[\\d ()-]{7,}\\d)(?!\\w)\', \'[number removed]\', text)\n    return text\n\ndef example_id(messages):\n    return hashlib.sha256(json.dumps(messages, sort_keys=True).encode()).hexdigest()\n\ndef eligible(row, snapshot=None):\n    if row.get(\'reviewStatus\') != \'approved\': return False\n    source = row.get(\'source\', {})\n    if source.get(\'kind\') == \'user\':\n        if not snapshot: return False\n        profile = snapshot.get(\'accounts\', {}).get(source.get(\'accountKey\'))\n        owner = snapshot.get(\'training\', {}).get(source.get(\'owner\'))\n        if not profile or profile.get(\'improve\') is not True or not owner or owner.get(\'revoked\'): return False\n        if profile.get(\'trainingGeneration\', 0) != source.get(\'generation\'): return False\n        original = owner.get(\'samples\', {}).get(source.get(\'chatId\'), {}).get(source.get(\'turnId\'))\n        if not original or original.get(\'consentVersion\') != 1: return False\n        # An export cannot be modified into different content while claiming old consent.\n        messages = [{\'role\': m[\'role\'], \'content\': redact(m[\'content\'])} for m in original.get(\'messages\', [])]\n        # Reviewers may correct the answer, but cannot replace the consented user prompt.\n        if not messages or not row.get(\'messages\') or row[\'messages\'][0] != messages[0]: return False\n    elif source.get(\'kind\') == \'teacher\':\n        if source.get(\'trainingAllowed\') is not True: return False\n    elif source.get(\'kind\') == \'public\':\n        allowed = (source.get(\'dataset\') == \'HuggingFaceTB/everyday-conversations-llama3.1-2k\' and source.get(\'subset\') == \'default\') or (source.get(\'dataset\') == \'HuggingFaceTB/smoltalk\' and source.get(\'subset\') == \'smol-magpie-ultra\')\n        story = source.get(\'dataset\') == \'roneneldan/TinyStories\' and source.get(\'subset\') == \'default\' and source.get(\'license\') == \'cdla-sharing-1.0\'\n        if not ((allowed and source.get(\'license\') == \'apache-2.0\') or story) or not source.get(\'recordId\'): return False\n    elif source.get(\'kind\') != \'seed\': return False\n    messages = row.get(\'messages\')\n    # User exports remain a single consent-checked pair. Owned/teacher datasets may be dialogues.\n    maximum = 2 if source.get(\'kind\') == \'user\' else 12\n    return (isinstance(messages, list) and 2 <= len(messages) <= maximum and len(messages) % 2 == 0\n            and all(isinstance(m, dict) and m.get(\'role\') == (\'user\' if i % 2 == 0 else \'assistant\')\n                    and isinstance(m.get(\'content\'), str) and 0 < len(m[\'content\'].strip()) <= 16000\n                    for i, m in enumerate(messages)))\n\ndef prepare(inputs, output, snapshot=None):\n    rows, seen = [], set()\n    for path in inputs:\n        for row in read_jsonl(path):\n            if not eligible(row, snapshot): continue\n            identifier = example_id(row[\'messages\'])\n            if identifier in seen: continue\n            seen.add(identifier); rows.append({**row, \'id\': identifier})\n    if not rows: raise ValueError(\'No approved, currently eligible training examples\')\n    write_jsonl(output, rows)\n    return len(rows)\n\ndef generate_teacher(config, prompts, output, limit=10, transport=None):\n    """Bounded calls to an OpenAI-compatible API. Original prompts only."""\n    if not 1 <= limit <= 100: raise ValueError(\'Request limit must be 1 to 100\')\n    if config.get(\'trainingAllowed\') is not True: raise ValueError(\'Choose a teacher whose output may be used for training\')\n    endpoint = config[\'url\']; parsed = urlparse(endpoint)\n    if parsed.username or parsed.password or parsed.query: raise ValueError(\'Credentials belong in an environment variable\')\n    if parsed.scheme != \'https\' and not (parsed.scheme == \'http\' and parsed.hostname in [\'localhost\', \'127.0.0.1\', \'::1\']): raise ValueError(\'HTTPS required for remote teacher\')\n    key = os.environ.get(config.get(\'keyEnv\', \'NEBULA_TEACHER_KEY\'), \'\')\n    if not key and parsed.hostname not in [\'localhost\', \'127.0.0.1\', \'::1\']: raise ValueError(\'Teacher API key is missing\')\n    rows = read_jsonl(output) if Path(output).exists() else []\n    completed = {r.get(\'promptId\') for r in rows}\n    calls = 0\n    for prompt in prompts:\n        # Prevent accidental transmission of exported user conversations to teachers.\n        if prompt.get(\'source\') != \'original\' or not isinstance(prompt.get(\'prompt\'), str): raise ValueError(\'Teacher prompts must be original curriculum prompts\')\n        text = prompt[\'prompt\'].strip()\n        if not text or len(text) > 4000: raise ValueError(\'Invalid curriculum prompt\')\n        identifier = hashlib.sha256((config.get(\'name\', \'custom\') + \':\' + config[\'model\'] + \':\' + text).encode()).hexdigest()\n        if identifier in completed: continue\n        if calls >= limit: break\n        payload = {\'model\': config[\'model\'], \'messages\': [{\'role\': \'system\', \'content\': \'Create a training example for Nebula using these owner instructions.\\n\' + owner_instructions() + \'\\n\' + config.get(\'instructions\', \'\')}, {\'role\': \'user\', \'content\': text}], \'max_tokens\': min(int(config.get(\'maxTokens\', 256)), 1024), \'temperature\': 0.6}\n        if config.get(\'temperature\', 0.6) is None: payload.pop(\'temperature\')\n        if config.get(\'reasoningEffort\') in [\'low\',\'medium\',\'high\']: payload[\'reasoning_effort\'] = config[\'reasoningEffort\']\n        request = Request(endpoint, json.dumps(payload).encode(), {\'Content-Type\': \'application/json\', \'User-Agent\':\'Nebula-Teacher/1.0\', **({\'Authorization\': \'Bearer \' + key} if key else {})})\n        if calls and not transport:\n            delay = min(60, max(0, float(config.get(\'requestIntervalSeconds\', 0))))\n            if delay: time.sleep(delay)\n        if transport: data = transport(request)\n        else:\n            # Never follow a redirect carrying a credential to another host.\n            from urllib.request import build_opener, HTTPRedirectHandler\n            class NoRedirect(HTTPRedirectHandler):\n                def redirect_request(self, *args, **kwargs): return None\n            data = request_json(build_opener(NoRedirect), request, provider=config.get(\'name\',\'teacher\'), max_retries=int(config.get(\'httpRetries\',2)))\n        answer = data[\'choices\'][0][\'message\'][\'content\']\n        if not isinstance(answer, str) or not answer.strip() or len(answer) > 16000: raise ValueError(\'Invalid teacher answer\')\n        rows.append({\'promptId\': identifier, \'reviewStatus\': \'pending\', \'messages\': [{\'role\': \'user\', \'content\': text}, {\'role\': \'assistant\', \'content\': redact(answer)}], \'source\': {\'kind\': \'teacher\', \'provider\': config.get(\'name\', \'custom\'), \'model\': config[\'model\'], \'trainingAllowed\': True}})\n        calls += 1; completed.add(identifier); write_jsonl(output, rows)\n    return calls\n', 'model/teacher_http.py': '"""Bounded HTTP retries and credential-free quota diagnostics."""\nimport json\nimport math\nimport re\nimport time\nfrom urllib.error import HTTPError\n\nclass TeacherRequestError(ValueError):\n    def __init__(self, message, status=429, retry_after=60, retryable=True):\n        super().__init__(message)\n        self.status = status\n        self.retry_after = retry_after\n        self.retryable = retryable\n\ndef quota_info(error):\n    result = {\'zero\': False, \'daily\': False, \'retry\': None}\n    try:\n        raw = error.read(200001)\n        if len(raw) > 200000: return result\n        value = json.loads(raw).get(\'error\', {})\n        message = str(value.get(\'message\', \'\'))\n        result[\'zero\'] = bool(re.search(r\'limit\\s*:\\s*0(?:\\D|$)\', message, re.I))\n        for detail in value.get(\'details\', []):\n            if not isinstance(detail, dict): continue\n            if str(detail.get(\'@type\', \'\')).endswith(\'RetryInfo\'):\n                match = re.fullmatch(r\'(\\d+(?:\\.\\d+)?)s\', str(detail.get(\'retryDelay\', \'\')))\n                if match: result[\'retry\'] = math.ceil(float(match[1]))\n            if str(detail.get(\'@type\', \'\')).endswith(\'QuotaFailure\'):\n                for violation in detail.get(\'violations\', []):\n                    if not isinstance(violation, dict): continue\n                    if str(violation.get(\'quotaValue\', \'\')) == \'0\': result[\'zero\'] = True\n                    if \'perday\' in str(violation.get(\'quotaId\', \'\')).lower(): result[\'daily\'] = True\n        header = error.headers.get(\'Retry-After\') if error.headers else None\n        if header and header.isdigit(): result[\'retry\'] = max(result[\'retry\'] or 0, int(header))\n    except (ValueError, TypeError, AttributeError, OSError): pass\n    return result\n\ndef request_json(opener, request, sleep=time.sleep, provider=\'gemini\', max_retries=2):\n    label = \'Groq\' if provider == \'groq\' else \'Gemini secondary\' if provider == \'gemini-secondary\' else \'Gemini\' if provider == \'gemini\' else \'Teacher\'\n    quota_url = \'https://console.groq.com/settings/limits\' if provider == \'groq\' else \'https://aistudio.google.com/rate-limit\' if provider in [\'gemini\',\'gemini-secondary\'] else \'your provider quota dashboard\'\n    for attempt in range(max_retries + 1):\n        try:\n            with opener.open(request, timeout=60) as response:\n                raw = response.read(200001)\n                if len(raw) > 200000: raise ValueError(\'Teacher reply too large\')\n                return json.loads(raw)\n        except HTTPError as error:\n            if error.code != 429: raise\n            info = quota_info(error)\n            if info[\'zero\']:\n                raise TeacherRequestError(f\'{label} HTTP 429: this model has a zero quota limit for your project. Check {quota_url} and select a model with available quota. Retrying cannot change a zero limit.\', retryable=False) from None\n            if info[\'daily\']:\n                raise TeacherRequestError(f\'{label} HTTP 429: daily quota exhausted. Check {quota_url} for the reset. Completed examples remain saved.\', retryable=False) from None\n            delay = max(15 * (2 ** attempt), info[\'retry\'] or 0)\n            if attempt == max_retries or delay > 60:\n                hint = f\' Provider suggests waiting {info["retry"]} seconds.\' if info[\'retry\'] is not None else \'\'\n                raise TeacherRequestError(f\'{label} HTTP 429: rate or quota limit still blocks requests.\' + hint + f\' Check {quota_url}. Completed examples remain saved.\', retry_after=max(60,info[\'retry\'] or 0)) from None\n            print(f\'{label} rate limited. Waiting {delay} seconds before retry {attempt + 1}/2. Ctrl+C stops.\', flush=True)\n            sleep(delay)\n', 'model/rules.py': '"""Owner instructions shared by training and private inference."""\nimport json\nimport os\nfrom pathlib import Path\n\ndef owner_instructions():\n    value = json.loads((Path(__file__).resolve().parent.parent / \'nebula-rules.json\').read_text(encoding=\'utf-8\'))\n    lines = value.get(\'instructions\')\n    if not isinstance(lines, list) or not lines or any(not isinstance(line, str) or not line.strip() for line in lines): raise ValueError(\'Invalid owner rules\')\n    extra = os.environ.get(\'NEBULA_OWNER_INSTRUCTIONS\', \'\')\n    text = \'\\n\'.join(lines + ([extra] if extra else []))\n    if len(text) > 16000: raise ValueError(\'Owner instructions too long\')\n    return text\n\ndef with_owner_rules(messages):\n    text = owner_instructions()\n    if messages and messages[0][\'role\'] == \'system\' and (messages[0][\'content\'] == text or messages[0][\'content\'].startswith(text + \'\\n\')): return messages\n    return [{\'role\': \'system\', \'content\': text}, *messages]\n', 'model/overnight.py': '"""V3: simple-language rehearsal, varied short tasks, and resumable GPU stages."""\nimport argparse\nimport hashlib\nimport json\nimport random\nimport time\nimport zlib\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport torch\nfrom dataflow import eligible,example_id,prepare,read_jsonl,write_jsonl\nfrom nebula import encode,load\nfrom rules import with_owner_rules\nfrom train import train\n\ndef curriculum():\n    """Original, exact-answer tasks with varied wording and bounded difficulty."""\n    rows=[]; seen=set()\n    def add(messages,group=None):\n        identifier=example_id(messages)\n        if identifier in seen: return\n        seen.add(identifier)\n        row={\'id\':identifier,\'reviewStatus\':\'approved\',\'source\':{\'kind\':\'seed\',\'curriculum\':\'nebula-v3\'},\'messages\':messages}\n        if group: row[\'splitGroup\']=group\n        rows.append(row)\n    def pair(q,a,group=None):\n        add([{\'role\':\'user\',\'content\':q},{\'role\':\'assistant\',\'content\':a}],group)\n    identities=[\'Introduce yourself.\',\'Who am I speaking with?\',\'Tell me who you are.\',\n                \'What should I call you?\',\'Please introduce yourself briefly.\',\'Which assistant are you?\',\n                \'Say your name.\',\'Do you have a name?\',\'Could you introduce yourself?\',\n                \'Identify yourself.\',\'What do people call you?\',\'Who is helping me?\']\n    for question in identities: pair(question,\'I am Nebula AI.\')\n    for question in [\'Hello there!\',\'Good morning!\',\'Hey Nebula!\',\'Hello, can we talk?\',\n                     \'Good evening!\',\'Hi there, Nebula.\',\'Hey, are you there?\',\'Greetings!\']:\n        pair(question,\'Hello! How can I help you?\')\n    for question in [\'Could you help me draft a message?\',\'I need to write a note.\',\n                     \'Help me write an email please.\',\'Can we draft an email together?\']:\n        pair(question,\'Yes. Who is it for, and what would you like to say?\')\n    for question in [\'What if you do not know an answer?\',\'Are your answers always right?\',\n                     \'Can you make mistakes?\',\'Will you admit when you are unsure?\']:\n        pair(question,\'I can make mistakes. I should tell you when I am unsure.\')\n    # Hold out whole name families: no alternate wording for a held-out person\'s\n    # scenario is allowed into training. These names differ from the old test Sam.\n    names=[\'Alice\',\'Amir\',\'Bella\',\'Cleo\',\'Diego\',\'Ella\',\'Felix\',\'Grace\',\'Hana\',\'Idris\',\n           \'Jade\',\'Kai\',\'Leah\',\'Luis\',\'Mila\',\'Nadia\',\'Oscar\',\'Priya\',\'Quinn\',\'Ravi\',\n           \'Sara\',\'Theo\',\'Uma\',\'Vera\',\'Will\',\'Xena\',\'Yara\',\'Zane\',\'Ada\',\'Eli\',\n           \'Flora\',\'Hugo\',\'Ines\',\'Jules\',\'Kira\',\'Luca\',\'Mina\',\'Owen\',\'Rosa\',\'Silas\']\n    colors=[\'red\',\'green\',\'blue\',\'yellow\',\'purple\',\'orange\']\n    for i,name in enumerate(names):\n        group=\'v3-person-\'+name\n        for question in [f\'My name is {name}. Please repeat it.\',\n                         f\'Please call me {name}. What should you call me?\',\n                         f\'I am {name}. Which name did I give you?\']:\n            pair(question,f\'Your name is {name}.\',group)\n        for color in colors:\n            pair(f\'{name} has a {color} bag. What color is the bag?\',f\'The bag is {color}.\',group)\n            pair(f\'The ball is {color}. Tell me its color.\',f\'The ball is {color}.\',\'v3-color-\'+color)\n            add([{\'role\':\'user\',\'content\':f\'Please call me {name}.\'},\n                 {\'role\':\'assistant\',\'content\':f\'Nice to meet you, {name}.\'},\n                 {\'role\':\'user\',\'content\':f\'My favorite color is {color}.\'},\n                 {\'role\':\'assistant\',\'content\':f\'I will keep that in mind in this conversation.\'},\n                 {\'role\':\'user\',\'content\':\'Which name and favorite color did I tell you?\'},\n                 {\'role\':\'assistant\',\'content\':f\'Your name is {name}, and your favorite color is {color}.\'}],group)\n        for animal in [\'cat\',\'dog\',\'bird\',\'fish\']:\n            pair(f\'{name} has a pet {animal}. What pet does {name} have?\',f\'{name} has a {animal}.\',group)\n    rng=random.Random(20261017)\n    operands=[(a,b) for a in range(31) for b in range(31)]\n    rng.shuffle(operands)\n    for i,(a,b) in enumerate(operands[:300]):\n        group=f\'v3-add-{min(a,b)}-{max(a,b)}\'\n        for question in [f\'Calculate {a} + {b}.\',f\'Add {a} and {b}.\',\n                         f\'I have {a} marbles and get {b} more. How many marbles do I have?\']:\n            pair(question,f\'{a} + {b} = {a+b}.\',group)\n    facts=[(\'What does a plant need to grow?\',\'Most plants need light, water, air, and nutrients.\'),\n           (\'What is a noun?\',\'A noun names a person, place, thing, or idea.\'),\n           (\'What is a verb?\',\'A verb describes an action or a state.\'),\n           (\'What is ice made of?\',\'Ice is frozen water.\'),\n           (\'What happens when ice gets warm?\',\'Ice melts into liquid water.\'),\n           (\'Why do people need sleep?\',\'Sleep helps the body and brain rest and recover.\'),\n           (\'What is a sentence?\',\'A sentence is a group of words that expresses a complete thought.\'),\n           (\'How can I write a polite request?\',\'Say what you need clearly and use polite words such as please.\'),\n           (\'What can I do if a task feels too big?\',\'Break it into smaller steps and start with one step.\'),\n           (\'How can I check an answer?\',\'Compare it with a reliable source or work through the steps again.\')]\n    for question,answer in facts: pair(question,answer)\n    return rows\n\ndef datasets(project):\n    data=Path(project)/\'model/data\'\n    own=data/\'v3-foundations.jsonl\'; write_jsonl(own,curriculum())\n    # The old language mix was dominated by long, complex instructions.\n    # Rehearse simpler stories and complete short dialogues instead.\n    dialogue=[]\n    for row in read_jsonl(data/\'improved-chat.jsonl\'):\n        if row.get(\'source\',{}).get(\'curriculum\')==\'nebula-foundations-v1\': continue\n        if eligible(row) and len(encode(with_owner_rules(row[\'messages\']))[0])<=1025:\n            dialogue.append(row)\n    conversations=data/\'v3-conversations.jsonl\'; write_jsonl(conversations,dialogue)\n    language=data/\'v3-language.jsonl\'; chat=data/\'v3-chat.jsonl\'\n    # Do not put the arithmetic curriculum into language rehearsal. It belongs\n    # to the second stage; basic language gets the larger training budget.\n    prepare([data/\'stories-approved.jsonl\',conversations],language)\n    prepare([conversations,own],chat)\n    print(json.dumps({\'v3LanguageConversations\':len(read_jsonl(language)),\n                      \'v3ChatConversations\':len(read_jsonl(chat)),\n                      \'newOriginalExercises\':len(curriculum()),\'downloadsNeeded\':False}),flush=True)\n    return language,chat\n\ndef backup_data(project):\n    """One downloadable data file, with checksums; no archive or credentials."""\n    project=Path(project); entries={}; hashes={}\n    names=[\'model/data/stories-approved.jsonl\',\'model/data/improved-chat.jsonl\',\n           \'model/data/v3-language.jsonl\',\'model/data/v3-chat.jsonl\',\n           \'model/data/v3-foundations.jsonl\',\'model/data/v3-conversations.jsonl\',\n           \'model/data/stories-sources.json\',\'model/data/public-sources.json\',\n           \'model/DATA_SOURCES.md\',\'nebula-rules.json\']\n    for name in names:\n        path=project/name\n        if not path.exists(): continue\n        raw=path.read_bytes(); hashes[name]=hashlib.sha256(raw).hexdigest()\n        entries[name]=torch.frombuffer(bytearray(zlib.compress(raw)),dtype=torch.uint8)\n    destination=project/\'Nebula_V3_Data.pt\'\n    temporary=destination.with_suffix(\'.tmp\')\n    torch.save({\'format\':\'nebula-v3-data-1\',\'compression\':\'zlib\',\'files\':entries,\'sha256\':hashes},temporary)\n    temporary.replace(destination)\n    return destination\n\ndef compare(checkpoints,project,label):\n    """Print actual replies on different questions; never fabricate a quality score."""\n    prompts=[\'Hello Nebula, who are you?\',\n             \'Calculate 13 + 9.\',\n             \'Please call me Talia. Which name did I give you?\',\n             \'Marta has a silver key. What color is her key?\',\n             \'Please write a polite, short thank-you note.\',\n             \'Tell a simple story about a lost puppy.\']\n    reports=[]\n    for path in checkpoints:\n        model,metadata=load(path); model.cuda()\n        for prompt in prompts:\n            answer=model.reply(with_owner_rules([{\'role\':\'user\',\'content\':prompt}]),max_tokens=180,temperature=0)\n            row={\'comparison\':label,\'checkpoint\':str(path),\'steps\':metadata.get(\'steps\'),\n                 \'prompt\':prompt,\'reply\':answer}\n            print(json.dumps(row),flush=True); reports.append(row)\n        del model; torch.cuda.empty_cache()\n    target=Path(project)/\'model/checkpoints\'/f\'{label}-replies.json\'\n    target.write_text(json.dumps(reports,indent=2),encoding=\'utf-8\')\n\ndef main(argv=None,on_data_ready=None):\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--project\',type=Path,required=True)\n    parser.add_argument(\'--hours\',type=float,default=8)\n    parser.add_argument(\'--batch\',type=int,default=16)\n    args=parser.parse_args(argv)\n    if not 0<args.hours<=12 or args.batch<1: parser.error(\'Use 0-12 hours and a positive batch size\')\n    if not torch.cuda.is_available(): raise RuntimeError(\'A GPU runtime is required\')\n    project=args.project; checkpoints=project/\'model/checkpoints\'\n    language,chat=datasets(project)\n    if on_data_ready:\n        backup=backup_data(project)\n        try: on_data_ready(backup)\n        except Exception as error:\n            print(json.dumps({\'dataBackupDownloadFailed\':type(error).__name__,\n                              \'downloadManually\':str(backup)}),flush=True)\n    deadline=time.monotonic()+args.hours*3600\n    # Preserve and inspect both previous stages. Continue language from its own\n    # best weights, rather than repeatedly undoing the latest chat tuning.\n    if not (checkpoints/\'v3-baseline-replies.json\').exists():\n        compare([checkpoints/\'previous-language.best.pt\',checkpoints/\'previous-chat.best.pt\'],project,\'v3-baseline\')\n    resume=checkpoints/\'previous-language.best.pt\'\n    plan=[(\'language\',language,20000,\'language\',.0001,deadline-args.hours*3600*.25),\n          (\'chat\',chat,8000,\'assistant\',.00005,deadline)]\n    for stage,data,limit,objective,lr,stage_deadline in plan:\n        output=checkpoints/f\'v3-{stage}.pt\'; best=output.with_suffix(\'.best.pt\')\n        marker=output.with_suffix(\'.done.json\')\n        if marker.exists() and best.exists(): resume=best; continue\n        done=0\n        if output.exists():\n            resume=output\n            _,meta=load(output); done=meta.get(\'stageSteps\',0)\n        remaining=limit-done; seconds=stage_deadline-time.monotonic()\n        if remaining<=0:\n            if not best.exists(): raise RuntimeError(\'Best checkpoint missing\')\n            resume=best; continue\n        if seconds<=0:\n            print(\'Time budget reached. Saved checkpoints remain available.\',flush=True)\n            return\n        batch=args.batch\n        while True:\n            print(json.dumps({\'v3Stage\':stage,\'resume\':str(resume),\'additionalSteps\':remaining,\n                              \'batch\':batch,\'maximumSeconds\':round(seconds),\'saveEvery\':200}),flush=True)\n            try:\n                result=train(SimpleNamespace(data=data,output=output,resume=resume,snapshot=None,\n                    steps=remaining,batch=batch,threads=2,seed=42,lr=lr,preset=\'cpu-large\',\n                    continuous=False,save_every=200,patience=10,device=\'cuda\',amp=True,\n                    objective=objective,grouped_split=True,bucketed=True,max_validation=256,\n                    save_training_state=True,max_seconds=seconds))\n            except torch.cuda.OutOfMemoryError:\n                if batch==1: raise\n            else: break\n            import gc\n            batch=max(1,batch//2); gc.collect(); torch.cuda.empty_cache()\n            if output.exists(): resume=output\n            seconds=stage_deadline-time.monotonic()\n            if seconds<=0: return\n        reason=result.get(\'reason\')\n        if result.get(\'stopped\') and reason not in [\'validation_not_improving\',\'time_limit\']:\n            print(\'Stopped safely. Next stage was not started.\',flush=True); return\n        if not best.exists(): raise RuntimeError(\'No validated checkpoint saved\')\n        marker.write_text(json.dumps(result),encoding=\'utf-8\')\n        resume=best\n        compare([best],project,f\'v3-{stage}\')\n        if time.monotonic()>=deadline: break\n    print(\'V3 run finished. Inspect v3-chat-replies.json and keep your previous model for comparison.\',flush=True)\n\nif __name__==\'__main__\': main()\n', 'model/evaluate.py': '"""Inspect a local checkpoint without teacher calls or deployment."""\nimport argparse\nimport json\nimport sys\nfrom pathlib import Path\n\nruntime = Path(__file__).resolve().parents[4] / \'work/nebula-python-deps\'\nif runtime.joinpath(\'torch\').is_dir(): sys.path.insert(0, str(runtime))\nimport torch\nfrom nebula import load\nfrom rules import with_owner_rules\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--checkpoint\', default=str(Path(__file__).resolve().parent/\'checkpoints/nebula-continuous.pt\'))\n    parser.add_argument(\'--device\', choices=[\'auto\',\'cpu\',\'cuda\'], default=\'auto\')\n    parser.add_argument(\'--temperature\', type=float, default=.7)\n    args = parser.parse_args()\n    torch.set_num_threads(2)\n    model, metadata = load(args.checkpoint)\n    device=\'cuda\' if args.device==\'auto\' and torch.cuda.is_available() else \'cpu\' if args.device==\'auto\' else args.device\n    model.to(device)\n    print(json.dumps({\'checkpoint\': args.checkpoint, \'trainingSteps\': metadata.get(\'steps\'), \'validationLoss\': metadata.get(\'validationLoss\'), \'experimental\': True}), flush=True)\n    for prompt in [\'hi\', \'What is your name?\', \'What is 2 + 2?\', \'What is 7 + 8?\', \'Explain gravity simply.\', \'Can you help me write an email?\', \'My name is Sam. What is my name?\', \'Why is the sky blue?\', \'Tell me a short story.\', \'How do I boil an egg?\']:\n        torch.manual_seed(42)\n        reply = model.reply(with_owner_rules([{\'role\': \'user\', \'content\': prompt}]), max_tokens=120, temperature=args.temperature)\n        print(json.dumps({\'prompt\': prompt, \'reply\': reply}, ensure_ascii=True), flush=True)\n\nif __name__ == \'__main__\': main()\n'}
